<?php use VO\Support\Template; ob_start(); ?><h1>Configuración</h1><form method="post" action="/admin/configuracion" class="card"><input type="hidden" name="csrf" value="<?= Template::e($csrf) ?>"><h2>Pagos</h2><label><input type="checkbox" name="mp_enabled" value="1"<?= $enabled?' checked':'' ?>> Habilitar Mercado Pago</label><label>Access token <input type="password" name="mp_access_token" value="" autocomplete="new-password" placeholder="Dejar vacío para conservar"></label><label>Webhook secret <input type="password" name="mp_webhook_secret" value="" autocomplete="new-password" placeholder="Dejar vacío para conservar"></label><label>Instrucciones de transferencia <textarea name="transfer_instructions"><?= Template::e($instructions) ?></textarea></label><h2>Notificaciones</h2><label><input type="checkbox" name="notifications_enabled" value="1"<?= $notif['master']?' checked':'' ?>> Habilitar notificaciones a clientes</label><label><input type="checkbox" name="notifications_email_enabled" value="1"<?= $notif['email']?' checked':'' ?>> Notificaciones por email (SMTP)</label><label>Servidor SMTP <input type="text" name="smtp_host" value="<?= Template::e($notif['smtp_host']) ?>"></label><label>Puerto SMTP <input type="number" name="smtp_port" value="<?= Template::e($notif['smtp_port']) ?>" min="1" max="65535" placeholder="587"></label><label>Usuario SMTP <input type="text" name="smtp_username" value="<?= Template::e($notif['smtp_username']) ?>"></label><label>Contraseña SMTP <input type="password" name="smtp_password" value="" autocomplete="new-password" placeholder="Dejar vacío para conservar"></label><label>Email del remitente <input type="text" name="smtp_from_email" value="<?= Template::e($notif['smtp_from_email']) ?>"></label><label>Nombre del remitente <input type="text" name="smtp_from_name" value="<?= Template::e($notif['smtp_from_name']) ?>"></label><label><input type="checkbox" name="notifications_whatsapp_enabled" value="1"<?= $notif['whatsapp']?' checked':'